/** Behavioral guidance copied from the same definitions clients discover. */
export function workflowReference(tools) {
  const lines = [
    "<!-- Generated by scripts/sync-mcp-surface.mjs. Do not edit by hand. -->",
    "", "# Research workflow and tool behavior", "",
    "Describe the decision and target population, reuse or create the relevant",
    "Audiences, and organize the research in a Study. Plan known questions as one",
    "complete block, review the exact draft revision before starting research,",
    "follow durable progress, inspect disagreement, and export the evidence.", "",
    "The detailed behavior below comes directly from production tool descriptions",
    "and schemas, including confirmation, file inputs, limits, retries, and export",
    "formats. It updates automatically when the server changes. Required marks",
    "refer to top-level schema requirements; conditional requirements are explained",
    "in each input's guidance and the complete schema.", "",
    "[Complete current input/output schemas](https://github.com/minds-ai-co/minds-mcp/blob/main/integrations/microsoft-mcp/mcptools.json)", "",
  ];
  const cell = value => String(value ?? "").replace(/\s+/g, " ").replace(/\|/g, "\\|");
  for (const tool of tools) {
    lines.push(`## ${tool.title || tool.name}`, "", `Tool: \`${tool.name}\``, "", tool.description, "");
    const properties = Object.entries(tool.inputSchema.properties ?? {});
    if (!properties.length) {
      lines.push("This tool has no named inputs.", "");
      continue;
    }
    lines.push("| Input | Required | Type / allowed values | Guidance |", "| --- | --- | --- | --- |");
    for (const [name, schema] of properties) {
      const type = schema.enum ? schema.enum.map(value => JSON.stringify(value)).join(", ")
        : schema.const !== undefined ? JSON.stringify(schema.const) : schema.type ?? "See schema";
      const guidance = [schema.description];
      if (schema.default !== undefined) guidance.push(`Default: ${JSON.stringify(schema.default)}.`);
      lines.push(`| \`${name}\` | ${tool.inputSchema.required?.includes(name) ? "Yes" : "No"} | ${cell(type)} | ${cell(guidance.filter(Boolean).join(" "))} |`);
    }
    lines.push("");
  }
  return lines.join("\n");
}
